def forest(self, prefix, count, cap_max=3):
    rng = self.rng
    nodes = []
    for index in range(count):
        name = ident(rng, prefix, index)
        parent = None
        if index and rng.random() < .6:
            parent = nodes[rng.randrange(index)]['id']
            depth = 0
            table = {n['id']: n for n in nodes}
            walk = parent
            while walk is not None:
                depth += 1
                walk = table[walk]['parent']
            if depth >= 3:
                parent = None
            nodes.append({'id': name, 'parent': parent,
                      'capacity': rng.choice([1, 1, 2, 3, 4096, 0])})
    rng.shuffle(nodes)
    return nodes

